from svg import box, t, arrow, svg

_O = [('COLLAPSE', 'the movement scatters', 'most Millerites, 1844'), ('SPLIT', 'rival heirs, rival churches', 'Mormons 1844; Moon 2012'),
      ('HARDEN', 'exposure is persecution', 'loyalists after a trial'), ('SETTLE', 'the sect becomes a church', 'Adventists, over decades')]
_inner = box(300, 20, 500, 64, 's-box-a') + t(550, 60, 'THE LEADER DIES, FAILS OR IS EXPOSED', 's-t')
for _i, (_a, _b, _c) in enumerate(_O):
    _x = 20 + _i * 270
    _inner += arrow(550, 86, _x + 125, 136) + box(_x, 140, 250, 96, 's-card') + t(_x + 125, 180, _a, 's-t-b') + t(_x + 125, 210, _b, 's-t-sm') + t(_x + 125, 270, _c, 's-t-sm')
FIG = svg(1100, 300, 'Four endings after the leader', _inner)

